<?phpnamespace App\Models;use CodeIgniter\Model;class CobroDetalleModel extends Model{    protected $table            = 'cobros_detalles';    protected $primaryKey       = 'detalle_id';    protected $useAutoIncrement = true;    protected $returnType       = 'array';    protected $allowedFields = [        'cobro_id', 'concepto_id', 'id_cuenta', 'id_partida',        'concepto_cantidad', 'concepto_monto', 'monto_catalogo', 'total', 'caracteristicas',    ];    protected $useTimestamps = true;    protected $createdField  = 'created_at';    protected $updatedField  = 'updated_at';}